 const h=FC.findIndex(c=>c[1].startsWith("Hoch's lawyer image"));if(h>=0)FC[h]=["know","Hoch's lawyer image (Davoudi 2012, exit ticket)","Planners don't uncover facts like geologists; like lawyers they organise facts as evidence within arguments (post-positivist)."];
 const p=FC.findIndex(c=>c[1]==="Policy-based evidence");if(p>=0)FC.splice(p,1);
 const e=FC.findIndex(c=>c[1].startsWith("Evidence-based vs evidence-informed"));if(e>=0)FC[e]=["davoudi","Evidence-based vs evidence-informed (Davoudi 2006)","Evidence-based: instrumental, linear hope that research determines policy. Evidence-informed: enlightenment model, where research clarifies context and informs debate."];
 const q=MCQ.find(x=>x.q.startsWith("'Planners do not uncover facts like geologists"));if(q){q.t="know";q.e="Exit ticket: Hoch, as used by Davoudi (2012), a post-positivist position.";}
 const q2=MCQ.find(x=>x.q.startsWith("Davoudi (2006) argues that 'evidence-based planning'"));if(q2){q2.o[1]="is largely rhetoric resting on an instrumental, linear view; in reality evidence competes with ideology, interests and institutions, so 'evidence-informed' is more realistic";}
